    add     rax, [rdi+280]
    adc     rcx, rbx              // h = hi0 + l1 + c1
    adc     rbp, 0                // h2 = hi1 + c2
    add     rax, r10              // s = t + cy0
    adc     rcx, r12              // cy0 = h + cy1
    adc     rbp, 0
    mov     [rdi+280], rax
    mov     [rdi+288], rcx
    mov     [rdi+296], rbp
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rbp
    pop     rbx
#ifdef LMMP_WINDOWS
    pop     rsi
    pop     rdi
#endif
    ret
